import React from 'react';

const certIcons = ['🎖','🏆','📜','🌟','✨','💎'];

const Certifications = ({ data }) => {
  const certs = data || [];

  return (
    <section style={{ padding:'100px 0' }}>
      <div style={{ maxWidth:1100, margin:'0 auto', padding:'0 2rem' }}>

        <div style={{ textAlign:'center', marginBottom:60 }}>
          <span style={{ fontFamily:"'DM Mono'", fontSize:'0.78rem', letterSpacing:'0.3em', textTransform:'uppercase', color:'#e8799a', display:'block', marginBottom:'0.75rem' }}>
            ✦ 05. achievements
          </span>
          <h2 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'clamp(2rem,5vw,3rem)', fontWeight:700, color:'#fdf0f4' }}>
            My <span style={{ color:'#e8b96a', fontStyle:'italic' }}>Certifications</span>
          </h2>
          <div style={{ width:60, height:3, background:'linear-gradient(90deg,#e8799a,#b882d4)', margin:'1.5rem auto 0', borderRadius:2 }} />
        </div>

        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(300px,1fr))', gap:'1.25rem' }}>
          {certs.map((cert, i) => {
            const parts = typeof cert === 'string' ? cert.split('-') : [cert, ''];
            const name  = parts[0]?.trim();
            const org   = parts[1]?.trim();
            return (
              <div key={i} style={{
                background:'rgba(34,18,40,0.72)',
                border:'1px solid rgba(232,121,154,0.12)',
                borderRadius:18, backdropFilter:'blur(14px)',
                padding:'1.5rem', display:'flex', gap:'1rem', alignItems:'flex-start',
                transition:'all 0.3s ease',
              }}
              onMouseEnter={e => { e.currentTarget.style.borderColor='rgba(232,121,154,0.4)'; e.currentTarget.style.transform='translateY(-3px)'; e.currentTarget.style.boxShadow='0 0 25px rgba(232,121,154,0.1)'; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor='rgba(232,121,154,0.12)'; e.currentTarget.style.transform='translateY(0)'; e.currentTarget.style.boxShadow='none'; }}
              >
                <div style={{ width:42, height:42, borderRadius:'50%', background:'linear-gradient(135deg,rgba(232,121,154,0.18),rgba(184,130,212,0.18))', border:'1px solid rgba(232,121,154,0.25)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'1.2rem', flexShrink:0 }}>{certIcons[i%certIcons.length]}</div>
                <div>
                  <div style={{ fontFamily:"'Nunito'", fontSize:'0.92rem', fontWeight:600, color:'#fdf0f4', marginBottom:'0.3rem', lineHeight:1.4 }}>{name}</div>
                  {org && <div style={{ fontFamily:"'DM Mono'", fontSize:'0.75rem', color:'#e8799a', letterSpacing:'0.05em' }}>{org}</div>}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
};

export default Certifications;
